package ru.ultimavox.itsm.servicedesk.api;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.net.URI; import org.springframework.http.ResponseEntity; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import ru.ultimavox.itsm.servicedesk.application.CreateWorkItem;
@RestController @RequestMapping("/api/v1/work-items") class CreateWorkItemController { private final CreateWorkItem create; CreateWorkItemController(CreateWorkItem create){this.create=create;} @PostMapping ResponseEntity<CreateWorkItem.Created> create(@Valid @RequestBody CreateRequest request, Authentication authentication){var result=create.create(new CreateWorkItem.Command(request.type(),request.title(),request.description(),request.service()),authentication.getName());return ResponseEntity.created(URI.create("/api/v1/work-items/"+result.id())).body(result);} record CreateRequest(@NotNull CreateWorkItem.Type type,@NotBlank @Size(max=240) String title,@NotBlank @Size(max=12000) String description,@NotBlank @Size(max=100) String service){} }
